def calculate_properties():
    from pymatgen.core import Structure
    from pymatgen.analysis.defects.supercells import _ase_cubic
    from pathlib import Path

    file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files/")
    gan_struct = Structure.from_file(file_path / "GaN.vasp")

    properties = {
        "supercell_size_constraint": None,
        "supercell_generation_failure": None
    }

    try:
        # Check supercell size constraint
        sc_mat = _ase_cubic(gan_struct, min_atoms=4, max_atoms=8, min_length=1.0)
        sc = gan_struct * sc_mat
        properties["supercell_size_constraint"] = 4 <= len(sc) <= 8
    except Exception:
        properties["supercell_size_constraint"] = None

    try:
        # Check supercell generation failure
        try:
            _ase_cubic(gan_struct, min_atoms=4, max_atoms=8, min_length=10.0)
            properties["supercell_generation_failure"] = False
        except RuntimeError:
            properties["supercell_generation_failure"] = True
    except Exception:
        properties["supercell_generation_failure"] = None

    return properties

def calculate_properties():
    try:
        test_dir = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files/")

        def gan_struct(test_dir):
            return Structure.from_file(test_dir / "GaN.vasp")

        def data_Mg_Ga(test_dir):
            root_dir = test_dir / "Mg_Ga"
            data = defaultdict(dict)
            for fold in root_dir.glob("./*"):
                if not fold.is_dir():
                    continue
                data[fold.name] = {
                    "vasprun": Vasprun(fold / "vasprun.xml.gz"),
                    "locpot": Locpot.from_file(fold / "LOCPOT.gz"),
                }
            return data

        def defect_Mg_Ga(gan_struct):
            ga_site = gan_struct[0]
            mg_site = PeriodicSite(Specie("Mg"), ga_site.frac_coords, gan_struct.lattice)
            return Substitution(gan_struct, mg_site)

        def defect_entries_and_plot_data_Mg_Ga(data_Mg_Ga, defect_Mg_Ga):
            bulk_locpot = data_Mg_Ga["bulk_sc"]["locpot"]

            def get_data(q):
                computed_entry = data_Mg_Ga[f"q={q}"]["vasprun"].get_computed_entry(
                    inc_structure=True
                )
                defect_locpot = data_Mg_Ga[f"q={q}"]["locpot"]

                def_entry = DefectEntry(
                    defect=defect_Mg_Ga, charge_state=q, sc_entry=computed_entry
                )
                frey_summary = def_entry.get_freysoldt_correction(
                    defect_locpot=defect_locpot, bulk_locpot=bulk_locpot, dielectric=14
                )
                return def_entry, frey_summary

            defect_entries = dict()
            plot_data = dict()
            for qq in [-2, -1, 0, 1]:
                defect_entry, frey_summary = get_data(qq)
                defect_entries[qq] = defect_entry
                plot_data[qq] = frey_summary.metadata["plot_data"]
            return defect_entries, plot_data

        def stable_entries_Mg_Ga_N(test_dir):
            return loadfn(test_dir / "stable_entries_Mg_Ga_N.json")

        def formation_energy_diagram(
            data_Mg_Ga, defect_entries_and_plot_data_Mg_Ga, stable_entries_Mg_Ga_N):
            bulk_vasprun = data_Mg_Ga["bulk_sc"]["vasprun"]
            bulk_bs = bulk_vasprun.get_band_structure()
            vbm = bulk_bs.get_vbm()["energy"]
            bulk_entry = bulk_vasprun.get_computed_entry(inc_structure=False)
            defect_entries, _ = defect_entries_and_plot_data_Mg_Ga

            def_ent_list = list(defect_entries.values())
            atomic_entries = list(
                filter(lambda x: len(x.composition.elements) == 1, stable_entries_Mg_Ga_N)
            )
            pd = PhaseDiagram(stable_entries_Mg_Ga_N)
            fed = FormationEnergyDiagram.with_atomic_entries(
                defect_entries=def_ent_list,
                atomic_entries=atomic_entries,
                vbm=vbm,
                inc_inf_values=False,
                phase_diagram=pd,
                bulk_entry=bulk_entry,
            )
            return fed

        gan_structure = gan_struct(test_dir)
        data_mg_ga = data_Mg_Ga(test_dir)
        defect_mg_ga = defect_Mg_Ga(gan_structure)
        defect_entries_and_plot_data = defect_entries_and_plot_data_Mg_Ga(data_mg_ga, defect_mg_ga)
        stable_entries = stable_entries_Mg_Ga_N(test_dir)
        fed = formation_energy_diagram(data_mg_ga, defect_entries_and_plot_data, stable_entries)

        competing_phases_at_chempot_limits = {}
        for limit, phases in fed.chempot_limits.items():
            competing_phases_at_chempot_limits[f"{limit}"] = set(phases)

        return {
            "competing_phases_at_chempot_limits": competing_phases_at_chempot_limits
        }
    except Exception as e:
        return {
            "competing_phases_at_chempot_limits": None
        }

def calculate_defect_properties():
    from pymatgen.core import Structure
    from pymatgen.analysis.defects.core import PeriodicSite, Substitution, Vacancy, Interstitial, DefectComplex
    from pymatgen.core.periodic_table import Specie, Element
    from pymatgen.core.composition import Composition

    results = {
        "defect_complex_name": None,
        "supercell_structure_formula": None,
        "defect_complex_oxidation_state": None,
        "element_changes": None,
        "defect_structure_formula": None,
        "defect_complex_with_interstitial_name": None,
        "supercell_structure_with_dummy_formula": None,
        "defect_complex_equality": None,
        "defect_complex_inequality": None
    }

    try:
        # Load the structure
        file_path = "tool_source_code/pymatgen-analysis-defects/tests/test_files/GaN.vasp"
        gan_struct = Structure.from_file(file_path)

        # Generate defects
        s = gan_struct.copy()
        o_site = PeriodicSite(Specie("O"), s[3].frac_coords, s.lattice)
        sub = Substitution(s, o_site)  # O substituted on N site
        vac = Vacancy(s, s.sites[0])  # Ga vacancy
        inter = Interstitial(s, PeriodicSite(Specie("H"), [0, 0, 0.75], s.lattice))  # H interstitial
        dc = DefectComplex([sub, vac])
        dc2 = DefectComplex([sub, vac, inter])

        # Calculate properties
        try:
            results["defect_complex_name"] = f"Substitution: {sub.name}, Vacancy: {vac.name}"
        except Exception:
            results["defect_complex_name"] = None

        try:
            supercell_structure = dc.defect_structure
            results["supercell_structure_formula"] = supercell_structure.composition.reduced_formula
        except Exception:
            results["supercell_structure_formula"] = None

        try:
            oxi_state_sum = sum(d.oxi_state for d in dc.defects)
            results["defect_complex_oxidation_state"] = (dc.oxi_state == oxi_state_sum)
        except Exception:
            results["defect_complex_oxidation_state"] = None

        try:
            results["element_changes"] = dc.element_changes
        except Exception:
            results["element_changes"] = None

        try:
            defect_structure = dc.defect_structure
            results["defect_structure_formula"] = defect_structure.composition.reduced_formula
        except Exception:
            results["defect_structure_formula"] = None

        try:
            results["defect_complex_with_interstitial_name"] = f"Substitution: {sub.name}, Vacancy: {vac.name}, Interstitial: {inter.name}"
        except Exception:
            results["defect_complex_with_interstitial_name"] = None

        try:
            supercell_with_dummy = dc2.defect_structure.copy()
            supercell_with_dummy.append("Xe", [0, 0, 0.75])
            results["supercell_structure_with_dummy_formula"] = supercell_with_dummy.composition.reduced_formula
        except Exception:
            results["supercell_structure_with_dummy_formula"] = None

        try:
            results["defect_complex_equality"] = (dc2 == dc2)
        except Exception:
            results["defect_complex_equality"] = None

        try:
            results["defect_complex_inequality"] = (dc != dc2)
        except Exception:
            results["defect_complex_inequality"] = None

    except Exception as e:
        # If any major error occurs, all properties will remain None
        pass

    return results

