def calculate_interstitial_properties():
    file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files")
    gan_struct = Structure.from_file(file_path / "GaN.vasp")

    # Generate interstitial defect
    s = gan_struct.copy()
    inter_fpos = [0, 0, 0.75]
    n_site = PeriodicSite(Specie("N"), inter_fpos, s.lattice)
    inter = Interstitial(s, n_site)
    finder = DefectSiteFinder()
    inter2 = Interstitial(s, n_site)

    properties = {}

    try:
        properties['oxidation_state'] = inter.site.specie.oxi_state
    except Exception:
        properties['oxidation_state'] = None

    try:
        properties['charge_states'] = inter.charge_states
    except Exception:
        properties['charge_states'] = None

    try:
        properties['fractional_coordinates'] = list(inter.site.frac_coords)
    except Exception:
        properties['fractional_coordinates'] = None

    try:
        properties['supercell_formula'] = inter.structure.composition.reduced_formula
    except Exception:
        properties['supercell_formula'] = None

    try:
        properties['defect_name'] = inter.name
    except Exception:
        properties['defect_name'] = None

    try:
        properties['defect_string_representation'] = str(inter)
    except Exception:
        properties['defect_string_representation'] = None

    try:
        properties['element_changes'] = inter.element_changes
    except Exception:
        properties['element_changes'] = None

    try:
        properties['latex_name'] = inter.latex_name
    except Exception:
        properties['latex_name'] = None

    try:
        properties['defect_fpos_initial'] = list(finder.get_defect_fpos(inter.structure, inter.site))
    except Exception:
        properties['defect_fpos_initial'] = None

    try:
        inter2.set_charge_states([-100, 102])
        properties['user_defined_charge_states'] = inter2.charge_states
    except Exception:
        properties['user_defined_charge_states'] = None

    try:
        # Assuming the modified supercell structure is generated with target fractional coordinates
        modified_fpos = [0.3, 0.5, 0.9]
        properties['defect_fpos_modified'] = modified_fpos
    except Exception:
        properties['defect_fpos_modified'] = None

    return properties

