        gan_struct = Structure.from_file(file_path / "GaN.vasp")

        # Initialize SubstitutionGenerator
        sub_gen = SubstitutionGenerator()

        # Calculate defect_type
        try:
            # Generate substitutional defects
            substitutions = {"Ga": ["Mg", "Ca"]}
            defects = list(sub_gen.generate(gan_struct, substitutions=substitutions))
            results["defect_type"] = all(isinstance(defect, SubstitutionGenerator) for defect in defects)
        except Exception:
            results["defect_type"] = None

        # Calculate replaced_atoms_set_1
        try:
            # Generate substitutional defects for Ga replaced by Mg and Ca
            substitutions = {"Ga": ["Mg", "Ca"]}
            defects = list(sub_gen.generate(gan_struct, substitutions=substitutions))
            replaced_atoms_1 = {defect.defect_structure.elements[defect.defect_site_index].symbol for defect in defects}
            results["replaced_atoms_set_1"] = replaced_atoms_1
        except Exception:
            results["replaced_atoms_set_1"] = None

