def calculate_vacancy_properties():
    from pymatgen.core import Structure
    from pymatgen.analysis.defects.core import Vacancy
    from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
    from pathlib import Path

    file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files")

    try:
        gan_struct = Structure.from_file(file_path / "GaN.vasp")
    except Exception as e:
        return {prop: None for prop in [
            "symmetry_equivalence", "vacancy_string_representation", "vacancy_oxidation_state",
            "vacancy_charge_states", "vacancy_multiplicity", "vacancy_supercell_formula",
            "vacancy_name", "vacancy_self_equivalence", "vacancy_element_changes", "vacancy_latex_name"
        ]}

    try:
        s = gan_struct.copy()
        vac = Vacancy(s, s.sites[0])
        vac2 = Vacancy(s, s.sites[1])
    except Exception as e:
        return {prop: None for prop in [
            "symmetry_equivalence", "vacancy_string_representation", "vacancy_oxidation_state",
            "vacancy_charge_states", "vacancy_multiplicity", "vacancy_supercell_formula",
            "vacancy_name", "vacancy_self_equivalence", "vacancy_element_changes", "vacancy_latex_name"
        ]}

    results = {}

    # Check symmetry equivalence
    try:
        analyzer = SpacegroupAnalyzer(s)
        symm_struct = analyzer.get_symmetrized_structure()
        results["symmetry_equivalence"] = symm_struct.are_symmetrically_equivalent([vac.defect_site], [vac2.defect_site])
    except Exception:
        results["symmetry_equivalence"] = None

    # String representation of the vacancy defect
    try:
        results["vacancy_string_representation"] = repr(vac)
    except Exception:
        results["vacancy_string_representation"] = None

    # Oxidation state of the vacancy defect
    try:
        results["vacancy_oxidation_state"] = int(vac._guess_oxi_state())
    except Exception:
        results["vacancy_oxidation_state"] = None

    # Possible charge states for the vacancy defect
    try:
        results["vacancy_charge_states"] = [int(vac._guess_oxi_state())]
    except Exception:
        results["vacancy_charge_states"] = None

    # Multiplicity of the vacancy defect
    try:
        results["vacancy_multiplicity"] = vac.get_multiplicity()
    except Exception:
        results["vacancy_multiplicity"] = None

    # Chemical formula of the supercell structure containing the vacancy defect
    try:
        defect_structure = vac.defect_structure
        results["vacancy_supercell_formula"] = defect_structure.composition.reduced_formula
    except Exception:
        results["vacancy_supercell_formula"] = None

    # Name of the vacancy defect
    try:
        results["vacancy_name"] = vac.name
    except Exception:
        results["vacancy_name"] = None

    # Check if the vacancy defect is equivalent to itself
    try:
        results["vacancy_self_equivalence"] = symm_struct.are_symmetrically_equivalent([vac.defect_site], [vac.defect_site])
    except Exception:
        results["vacancy_self_equivalence"] = None

    # Changes in the number of elements due to the vacancy defect
    try:
        results["vacancy_element_changes"] = vac.element_changes
    except Exception:
        results["vacancy_element_changes"] = None

    # LaTeX formatted name of the vacancy defect
    try:
        results["vacancy_latex_name"] = f"v_{{{vac.defect_site.specie.symbol}}}"
    except Exception:
        results["vacancy_latex_name"] = None

    return results
